    payload?.hubspot_deal_id ?? payload?.metadata?.hubspot_deal_id ?? payload?.crm?.hubspot_deal_id ?? null,
  );
}

function detectTranscriptSource(payload, sourceHint) {
  const hint = sourceHint ? String(sourceHint).trim().toLowerCase() : '';
